const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const OPEN=[1,2,3,4];const HOURS=[14,15,16,17,18];
let today=null,sessions=[],rules=[],revs={};
const $=id=>document.getElementById(id);
function say(t,kind){const s=$('status');s.textContent=t;s.className=kind||'';}
function pad(n){return String(n).padStart(2,'0');}
function dayOffset(wd){const p=today.split('-').map(Number);const dow=new Date(Date.UTC(p[0],p[1]-1,p[2])).getUTCDay();return (wd-dow+7)%7;}
function dateFor(wd){const p=today.split('-').map(Number);const d=new Date(Date.UTC(p[0],p[1]-1,p[2]+dayOffset(wd)));return d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate());}
function hourText(h){return (h>12?h-12:h)+':00 '+(h>=12?'pm':'am');}
function banned(extra){const s=new Set(rules.map(r=>r.weekday));if(extra!==undefined)s.add(extra);return s;}
function slotsInOrder(ban){const out=[];const days=OPEN.filter(d=>!ban.has(d)).sort((a,b)=>dayOffset(a)-dayOffset(b));for(const d of days)for(const h of HOURS)out.push({weekday:d,hour:h});return out;}
function key(wd,h){return wd+'-'+h;}
async function load(){const r=await tessera.call('data.read',{});sessions=r.data.sessions||[];rules=r.data.rules||[];revs=r.revisions||{};}
function render(){
 const ul=$('sessions');ul.textContent='';
 const list=sessions.slice().sort((a,b)=>dayOffset(a.weekday)-dayOffset(b.weekday)||a.hour-b.hour||a.weekday-b.weekday);
 $('empty').hidden=list.length>0;
 for(const s of list){
  const li=document.createElement('li');li.setAttribute('data-hook','session');
  const left=document.createElement('span');
  const who=document.createElement('span');who.className='who';who.setAttribute('data-hook','session-task');who.textContent=s.student;
  const when=document.createElement('span');when.className='when';
  const t=document.createElement('time');t.setAttribute('datetime',dateFor(s.weekday));t.textContent=DAYS[s.weekday]+' '+dateFor(s.weekday);
  when.append(' · ',t,', '+hourText(s.hour)+'–'+hourText(s.hour+1));
  left.append(who,when);
  const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent='Cancel';b.setAttribute('aria-label','Cancel session for '+s.student);
  b.addEventListener('click',()=>cancel(s));
  li.append(left,b);ul.append(li);
 }
 const rl=$('rules');rl.textContent='';$('no-rules').hidden=rules.length>0;
 for(const r of rules){
  const li=document.createElement('li');li.setAttribute('data-hook','rule');
  const sp=document.createElement('span');sp.textContent='No sessions on '+DAYS[r.weekday]+'s';
  const b=document.createElement('button');b.type='button';b.className='secondary';b.setAttribute('data-hook','rule-remove');b.textContent='Remove';b.setAttribute('aria-label','Remove the rule for '+DAYS[r.weekday]);
  b.addEventListener('click',()=>removeRule(r));
  li.append(sp,b);rl.append(li);
 }
}
async function guard(fn){try{await fn();}catch(e){say('That did not work and nothing was changed. Please try again.','error');try{await load();render();}catch(_){}}}
async function addTask(){
 const inp=$('task-name');const name=inp.value.trim();
 if(!name){say('Type the student\'s name first.','error');inp.focus();return;}
 const taken=new Set(sessions.map(s=>key(s.weekday,s.hour)));
 const slot=slotsInOrder(banned()).find(x=>!taken.has(key(x.weekday,x.hour)));
 if(!slot){say('There is no free time left.','error');return;}
 await tessera.call('data.patch',{operations:[{op:'add',collection:'sessions',record:{student:name,weekday:slot.weekday,hour:slot.hour}}]});
 inp.value='';await load();render();
 say(name+' is booked on '+DAYS[slot.weekday]+' at '+hourText(slot.hour)+'.','ok');inp.focus();
}
async function addRule(){
 const wd=Number($('rule-day').value);
 if(rules.some(r=>r.weekday===wd)){say(DAYS[wd]+' is already blocked.','error');return;}
 const ban=banned(wd);
 const ops=[];const taken=new Set(sessions.filter(s=>!ban.has(s.weekday)).map(s=>key(s.weekday,s.hour)));
 const slots=slotsInOrder(ban);
 const moving=sessions.filter(s=>s.weekday===wd);
 let moved=0;
 for(const s of moving){
  let pick=slots.find(x=>x.hour===s.hour&&!taken.has(key(x.weekday,x.hour)));
  if(!pick)pick=slots.slice().sort((a,b)=>Math.abs(a.hour-s.hour)-Math.abs(b.hour-s.hour)).find(x=>!taken.has(key(x.weekday,x.hour)));
  if(!pick){say('Not enough free times to block '+DAYS[wd]+'. Nothing was changed.','error');return;}
  taken.add(key(pick.weekday,pick.hour));
  ops.push({op:'replace',collection:'sessions',id:s.id,revisionCount:(revs.sessions||{})[s.id]||1,fields:{weekday:pick.weekday,hour:pick.hour}});moved++;
 }
 ops.push({op:'add',collection:'rules',record:{weekday:wd}});
 await tessera.call('data.patch',{operations:ops});
 await load();render();
 say(DAYS[wd]+' is blocked.'+(moved?' '+moved+' session'+(moved>1?'s were':' was')+' moved to other days.':''),'ok');
}
async function removeRule(r){
 await tessera.call('data.patch',{operations:[{op:'remove',collection:'rules',id:r.id,revisionCount:(revs.rules||{})[r.id]||1}]});
 await load();render();say(DAYS[r.weekday]+' is open again. Existing sessions stay where they are.','ok');$('rule-day').focus();
}
async function cancel(s){
 await tessera.call('data.patch',{operations:[{op:'remove',collection:'sessions',id:s.id,revisionCount:(revs.sessions||{})[s.id]||1}]});
 await load();render();say('Session for '+s.student+' cancelled.','ok');$('task-name').focus();
}
$('task-add').addEventListener('click',()=>guard(addTask));
$('task-name').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();guard(addTask);}});
$('rule-add').addEventListener('click',()=>guard(addRule));
(async()=>{try{const c=await tessera.call('clock.now',{});today=c.date;await load();render();}catch(e){say('The sheet could not be opened. Please try again.','error');}})();
